package net.civeira.phylax.feature.notification.message.application.usecase.update;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.notification.message.domain.MessageChangeSet;

class MessageUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the message input values are kept when converted to a change set and back")
  void test_message_update_input_change_set_round_trip() {
    MessageUpdateInput input = MessageUpdateInput.builder().uid("one").target("one")
        .tenant(TenantReference.of("one")).urgent(true).content("one").retries(1)
        .createdAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .sendAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .lockAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .version(1).build();
    MessageChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    MessageUpdateInput copy = MessageUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTarget().isPresent(), "target must be assigned by the builder");
    Assertions.assertEquals(input.getTarget(), copy.getTarget(),
        "target must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getUrgent().isPresent(), "urgent must be assigned by the builder");
    Assertions.assertEquals(input.getUrgent(), copy.getUrgent(),
        "urgent must survive the change set round trip");
    Assertions.assertTrue(input.getContent().isPresent(),
        "content must be assigned by the builder");
    Assertions.assertEquals(input.getContent(), copy.getContent(),
        "content must survive the change set round trip");
    Assertions.assertTrue(input.getRetries().isPresent(),
        "retries must be assigned by the builder");
    Assertions.assertEquals(input.getRetries(), copy.getRetries(),
        "retries must survive the change set round trip");
    Assertions.assertTrue(input.getCreatedAt().isPresent(),
        "createdAt must be assigned by the builder");
    Assertions.assertEquals(input.getCreatedAt(), copy.getCreatedAt(),
        "createdAt must survive the change set round trip");
    Assertions.assertTrue(input.getSendAt().isPresent(), "sendAt must be assigned by the builder");
    Assertions.assertEquals(input.getSendAt(), copy.getSendAt(),
        "sendAt must survive the change set round trip");
    Assertions.assertTrue(input.getLockAt().isPresent(), "lockAt must be assigned by the builder");
    Assertions.assertEquals(input.getLockAt(), copy.getLockAt(),
        "lockAt must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the message input builder can generate a new identifier")
  void test_message_update_input_new_uid() {
    MessageUpdateInput input = MessageUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        MessageUpdateInput.builder().newUid().build().getUid(), "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the message input starts empty and the setters assign values")
  void test_message_update_input_setters() {
    MessageUpdateInput empty = MessageUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTarget().isEmpty(), "target must be empty by default");
    Assertions.assertSame(empty, empty.setTarget("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTarget().isPresent(), "target must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getUrgent().isEmpty(), "urgent must be empty by default");
    Assertions.assertSame(empty, empty.setUrgent(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUrgent().isPresent(), "urgent must be assigned by the setter");
    Assertions.assertTrue(empty.getContent().isEmpty(), "content must be empty by default");
    Assertions.assertSame(empty, empty.setContent("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getContent().isPresent(), "content must be assigned by the setter");
    Assertions.assertTrue(empty.getRetries().isEmpty(), "retries must be empty by default");
    Assertions.assertSame(empty, empty.setRetries(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetries().isPresent(), "retries must be assigned by the setter");
    Assertions.assertTrue(empty.getCreatedAt().isEmpty(), "createdAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setCreatedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCreatedAt().isPresent(),
        "createdAt must be assigned by the setter");
    Assertions.assertTrue(empty.getSendAt().isEmpty(), "sendAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setSendAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getSendAt().isPresent(), "sendAt must be assigned by the setter");
    Assertions.assertTrue(empty.getLockAt().isEmpty(), "lockAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setLockAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLockAt().isPresent(), "lockAt must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
